import {pulleyRadius,beltLength} from './belt-parts.js';
import {V,Q,definition,part,busy,exportModel,parseModel} from './engine.js';
import {Matrix4} from './vendor/three.module.js';
export function pulleyPair(a,b){const ra=pulleyRadius(definition(a)),rb=pulleyRadius(definition(b));if(!ra||!rb||a.id===b.id)throw Error('Choose two different Classic hub/pulleys.');const axis=V([0,0,1]).applyQuaternion(Q(a.quat)),axisB=V([0,0,1]).applyQuaternion(Q(b.quat)),delta=V(b.pos).sub(V(a.pos)),span=delta.length();if(Math.abs(axis.dot(axisB))<.99999||Math.abs(delta.dot(axis))>.1)throw Error('Align the two pulley grooves in one plane on parallel axles.');if(span<=ra+rb+3||span>1000)throw Error('Separate the pulleys without overlapping their rims (maximum preview span 1000 mm).');const x=delta.normalize(),y=axis.clone().cross(x).normalize(),quat=Q().setFromRotationMatrix(new Matrix4().makeBasis(x,y,axis)).toArray(),belt={span,radii:[ra,rb]};return{belt,pos:[...a.pos],quat,length:beltLength(belt)};}
export function fitBelt(source,aId,bId,{bandId=null}={}){const m=parseModel(exportModel(source)),a=m.parts.find(p=>p.id===aId),b=m.parts.find(p=>p.id===bId);if(!a||!b)throw Error('Select two pulleys.');const existing=bandId&&m.parts.find(p=>p.id===bandId&&definition(p).belt);if(bandId&&!existing)throw Error('The selected band is no longer available.');if(existing)m.links=m.links.filter(l=>l.a!==bandId&&l.b!==bandId);if(!existing&&m.parts.length>=2500)throw Error('Maximum 2500 parts per model.');for(const p of[a,b])if(busy(m,p.id,'groove')||m.links.some(l=>l.mode==='tire'&&(l.a===p.id||l.b===p.id)))throw Error('A pulley groove is already occupied by a belt or tyre.');const layout=pulleyPair(a,b),band=existing||part('band-brown',layout.pos,layout.quat);if(band.grounded)throw Error('Unlock the band before refitting it.');band.pos=layout.pos;band.quat=layout.quat;band.belt=layout.belt;if(!existing)m.parts.push(band);m.links.push({a:a.id,ap:'groove',b:band.id,bp:'seat0',mode:'belt'},{a:b.id,ap:'groove',b:band.id,bp:'seat1',mode:'belt'});return{model:m,band,length:layout.length};}
export function beltEdges(model){return model.parts.filter(p=>definition(p).belt).map(band=>{const links=model.links.filter(l=>l.mode==='belt'&&(l.a===band.id||l.b===band.id)),host=seat=>{const l=links.find(l=>(l.a===band.id?l.ap:l.bp)===seat);return l&&(l.a===band.id?l.b:l.a);};return{a:host('seat0'),b:host('seat1'),band,mode:'belt'};});}
export function validateBeltDrive(edge,a,b){if(edge.band.grounded)throw Error('Unlock the pulley band before running the drive.');if(!a||!b)throw Error('Reconnect both ends of the pulley band before running.');const layout=pulleyPair(a,b),band=edge.band,q=Q(band.quat),axis=V([0,0,1]).applyQuaternion(q),x=V([1,0,0]).applyQuaternion(q),expectedB=V(band.pos).addScaledVector(x,band.belt.span);if(V(a.pos).distanceTo(V(band.pos))>.1||V(b.pos).distanceTo(expectedB)>.1||Math.abs(axis.dot(V([0,0,1]).applyQuaternion(Q(a.quat))))<.99999||band.belt.radii.some((r,i)=>r!==layout.belt.radii[i]))throw Error('The pulley band no longer fits. Select the band and refit it after moving the pulleys.');return layout;}
